import { Suspense } from '@suspensive/react';
import clsx from 'clsx';
import { Fragment, useCallback, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { useParams } from 'react-router-dom';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useGetCodeManage } from '~/entities/comcode/api/use-comcode-api';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { useGetCmmntyManageQuery } from '~/entities/community/api/use-get-cmmnty-manage-query';
import { useOnSubmit } from '~/entities/community/lib/use-on-submit';
import { CommunityParams } from '~/entities/community/model/types';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { YesOrNo, CommunityTypeCode } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { SelectStyle } from '~/shared/ui/selects/base/types';
import { useSelectBottomSheet } from '~/shared/ui/selects/use-select-bottom-sheet';
import { TextInput } from '~/shared/ui/text-input/text-input';

export const InquiryModifyPage = () => {
  const { nttManageId } = useParams();
  const { data: userRes } = useGetUserInfoQuery();
  const { callModifyCmmntyManage } = useOnSubmit();
  const [conten, setConten] = useState(false);
  const { openSelectBottomSheet, closeBottomSheet } = useSelectBottomSheet<string>();
  const { data: codeData } = useGetCodeManage(COM_CODE.COMMUNITY_CATEGORY);
  const { data } = useGetCmmntyManageQuery(nttManageId ?? '');

  const form = useForm<CommunityParams>({
    mode: 'all',
    defaultValues: {
      cstmrNo: userRes?.tbCstmrMastr?.cstmrNo ?? '',
      nttManageId: data?.tbCmmntyMastr?.nttManageId ?? '',
      nttSj: data?.tbCmmntyMastr?.nttSj ?? '',
      nttCn: data?.tbCmmntyMastr?.nttCn ?? '',
      ctgry: data?.tbCmmntyMastr?.ctgry ?? '',
      ctgryNm: data?.tbCmmntyMastr?.ctgryNm ?? '',
      ntceYn: YesOrNo.예,
      nttTycd: CommunityTypeCode.일대일문의,
    },
  });
  const { watch, handleSubmit, register, setValue } = form;
  const { nttSj, nttCn, ctgryNm } = watch();
  const watchAllFields = watch();
  const isDisabled = !nttCn || !ctgryNm || !nttSj;
  const handleOpenTokenList = useCallback(() => {
    const values = codeData?.tbSysCodeValueList
      ? codeData?.tbSysCodeValueList?.map((value) => value.cdValue ?? '') ?? []
      : [];
    const labels = codeData?.tbSysCodeValueList
      ? codeData?.tbSysCodeValueList?.map((value) => value.cdValueNm ?? '') ?? []
      : [];

    openSelectBottomSheet({
      title: i18n.t('validation:chooseCategory'),
      options: values.map((value, index) => ({
        value: value as string,
        label: labels[index],
      })),
      selectedOption:
        ctgryNm && typeof ctgryNm === 'string'
          ? {
              value: values[labels.indexOf(ctgryNm)],
              label: ctgryNm,
            }
          : undefined,
      selectStyle: SelectStyle.DEFAULT,
      onRadioChange: ({ option }) => {
        setValue('ctgry', option.value);
        setValue('ctgryNm', option.label);
        closeBottomSheet();
      },
    });
  }, [codeData, ctgryNm, setValue, closeBottomSheet]);

  return (
    <Fragment>
      <div className="content sub has-btm-btn">
        <Suspense fallback={<FullScreenLoading />}>
          <div className="sub-desc">
            <p>{i18n.t('text:howCanWeHelp')}</p>
          </div>
          <FormProvider {...form}>
            <form onSubmit={handleSubmit(callModifyCmmntyManage)} className="ipt-form-area">
              <TextInput
                label={i18n.t('selectCategory')}
                {...register('ctgry')}
                readOnly
                onClick={handleOpenTokenList}
                displayLabel={ctgryNm ?? ''}
                selectMode={true}
                isErrorPaddingPresent={false}
              />
              <TextInput
                label={i18n.t('inquiryTitle')}
                {...register('nttSj')}
                isErrorPaddingPresent={false}
                maxLength={100}
              />
              <div className={`ipt-form text-area ${(nttCn ?? '')?.length > 0 ? 'on-data' : conten ? 'on-focus' : ''}`}>
                <label className="ipt-label">{i18n.t('validation:enterInquiryDetails')}</label>
                <div className="ipt-form-box">
                  <textarea
                    className="ipt-text"
                    {...register('nttCn')}
                    maxLength={500}
                    onFocus={() => setConten(true)}
                    onBlur={() => setConten(false)}
                    required
                  ></textarea>
                </div>
                <div className="ipt-desc text-cnt">
                  <span id="txtCnt">{nttCn?.length ?? 0}/500</span>
                </div>
              </div>
              <dl className="info-list">
                <dt>1:1문의 안내</dt>
                <dd>담당자 확인 즉시 답변해 드립니다.</dd>
                <dd>등록하신 문의의 답변이 완료된 경우 새로운 문의 작성하기로 추가 문의 부탁드립니다.</dd>
              </dl>
            </form>
          </FormProvider>
        </Suspense>
      </div>
      <div className="btm-btn-area">
        <button
          type="button"
          disabled={isDisabled}
          className={clsx('btm-btn app', {
            disabled: isDisabled,
          })}
          onClick={() => callModifyCmmntyManage(watchAllFields)}
        >
          {i18n.t('register')}
        </button>
      </div>
    </Fragment>
  );
};
